-- TortoiseBotsForever -- DRAFT NPC rows: <Mercenary Hire> recruiters and credit-only creatures.
-- DO NOT APPLY until the port registers the ids and script (see npcs-sql-notes.md).
--
-- client_build: "client DB2 70938 (2026-11-17); world/hotfixes TDB 2026-10-14"
-- Sources (TortoiseBots world migrations, final state after all in-place fixes):
--   20260918120000_world.sql  original 68 recruiter templates + spawns (superseded)
--   20260925100000_world.sql  68 opposite-gender display/name updates (re-applied inline)
--   20260928100000_world.sql  68 templates + 67 spawns with explicit guids 4000000-4000066 (current base)
--   20261005090000_world.sql  world-buff credit creatures 95100/95101; npc_flags=3 on 6 capital recruiters
--   20261005120000_world.sql  renames 95100/95101
--   20261012220000_world.sql  spawn 4000033 (95032 Kerra) movement_type 2 -> 0
--   20261013090000_world.sql  hire-unlock credit creatures 95110-95121
--   20261026120000_world.sql  npc_text/broadcast_text greetings (regenerated here from the final names)
--
-- Renumbering: recruiters 95000-95067 -> 1000000-1000067; world-buff credits 95100/95101 -> 1000070/1000071;
-- hire-unlock credits 95110-95121 -> 1000080-1000091. Greeting npc_text/broadcast_text ids equal the new
-- creature entry (and entry+100 for the AiPlayerbot.HireAllowPvP=1 variant), exactly as the module computes them.
-- Spawn guids are the TB ones (4000000-4000066): free in the Forever world DB, whose lowest creature guid is 20000001.
-- Display ids live in `creature_template_model` (Forever has no display columns on creature_template);
-- the 14 credit-only rows get the invisible display 11686 (same as TDB's own credit rows).
--
-- SECTION A targets the world database. SECTION B (`broadcast_text`) targets the hotfixes database:
-- Forever reads broadcast_text from the hotfixes DB (world DB has no such table).
-- Both sections are idempotent: every range is deleted before re-insertion.

-- ============================ SECTION A: world database ============================

DELETE FROM `creature_template` WHERE `entry` BETWEEN 1000000 AND 1000091;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 1000000 AND 1000091;
DELETE FROM `creature_classic_level` WHERE `entry` BETWEEN 1000000 AND 1000067;
DELETE FROM `creature` WHERE `guid` BETWEEN 4000000 AND 4000066 OR `id` BETWEEN 1000000 AND 1000091;
DELETE FROM `npc_text` WHERE `ID` BETWEEN 1000000 AND 1000067 OR `ID` BETWEEN 1000100 AND 1000167;

-- 68 recruiter templates (level forced to 30 by creature_classic_level below; health/mana/armor/damage are
-- derived by the 1.60 core from its own classic stat tables -- TB's handcrafted values have no Forever column).

-- One model per template (creature_template_model.CreatureDisplayID = TB display_id1).

-- Fixed vanilla level 30 for every recruiter (core: creature_classic_level).

-- 67 spawns: one per live innkeeper spawn (Fizzgrimble 1000029 and 1000062 twice; 1000042/1000066/1000067 have
-- no spawn, same as TB). Positions/orientations copied from 20260928100000_world.sql; map/z unchanged.

-- Greetings: npc_text ID = creature entry; BroadcastTextID0 points at the matching hotfixes row (Section B).
-- Probability0=1 / BroadcastTextID0=<same id>; the other 7 slots stay 0 (defaults).

-- ============================ SECTION B: hotfixes database ============================

DELETE FROM `broadcast_text` WHERE `ID` BETWEEN 1000000 AND 1000067 OR `ID` BETWEEN 1000100 AND 1000167;

-- VerifiedBuild=0 marks a custom hotfix row (Trinity convention), same text for male/female, LanguageID=0.
