INSERT INTO `broadcast_text` (`ID`, `Text`, `Text1`, `LanguageID`, `VerifiedBuild`) VALUES
(1000000, 'Greetings, $N. I am Marla, and I hire out mercenaries to those who need a strong arm on the road. Dungeons, wild lands, the dark places of the world: my companions will fight beside you.$B$B|cff9b0000These mercenaries are for PvE only. They leave you when you enter a battleground.|r', 'Greetings, $N. I am Marla, and I hire out mercenaries to those who need a strong arm on the road. Dungeons, wild lands, the dark places of the world: my companions will fight beside you.$B$B|cff9b0000These mercenaries are for PvE only. They leave you when you enter a battleground.|r', 0, 0),
